// This code handles user comments and checks for specific keywords
function analyzeComment(comment) {
    // List of keywords to identify negative sentiment
    const negativeKeywords = ['deception', 'lie', 'fraud', 'scam', 'cheat'];

    // Convert comment to lowercase for case-insensitive comparison
    const lowerCaseComment = comment.toLowerCase();

    // Check if any negative keyword is present in the comment
    for (let keyword of negativeKeywords) {
        if (lowerCaseComment.includes(keyword)) {
            return 'Negative sentiment detected: Accusation of deception.';
        }
    }

    return 'No negative sentiment detected.';
}

// Example usage
const userComment = 'Accusation of deception.';
console.log(analyzeComment(userComment));
```

